message:
Running command: cd /workspace && cat > /tmp/test_sav.c << 'EOF'
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#include "readstat.h"
#include "test_types.h"
#include "test_buffer.h"
#include "test_buffer_io.h"
#include "fuzz_format.h"

int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size);

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *data = malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    fprintf(stderr, "Testing with %ld bytes\n", size);
    int ret = LLVMFuzzerTestOneInput(data, size);
    fprintf(stderr, "Returned: %d\n", ret);
    free(data);
    return 0;
}
EOF

SRCDIR="repo-vul/src-vul/readstat/src"
INCLUDES="-I $SRCDIR -I $SRCDIR/spss -I $SRCDIR/sas -I $SRCDIR/stata -I $SRCDIR/test -I $SRCDIR/fuzz"
CFLAGS="-g -fsanitize=address $INCLUDES"

gcc $CFLAGS -c /tmp/test_sav.c -o /tmp/test_sav.o 2>&1
gcc $CFLAGS -c $SRCDIR/fuzz/fuzz_format.c -o /tmp/fuzz_format.o 2>&1

gcc -g -fsanitize=address \
  /tmp/test_sav.o /tmp/fuzz_format.o \
  /tmp/readstat_bits.o /tmp/readstat_convert.o /tmp/readstat_error.o \
  /tmp/readstat_malloc.o /tmp/readstat_metadata.o /tmp/readstat_parser.o \
  /tmp/readstat_value.o /tmp/readstat_variable.o \
  /tmp/readstat_sav.o /tmp/readstat_sav_compress.o /tmp/readstat_sav_parse.o \
  /tmp/readstat_sav_parse_timestamp.o /tmp/readstat_sav_read.o \
  /tmp/readstat_spss.o /tmp/readstat_spss_parse.o \
  /tmp/ieee.o /tmp/readstat_sas.o \
  /tmp/readstat_dta.o /tmp/readstat_dta_parse_timestamp.o \
  /tmp/CKHashTable.o \
  -o /tmp/test_sav_fuzzer 2>&1

echo "=== Linking done ==="

